<script setup lang="ts">import{useAimsModule}from'../useAimsModule';const{moduleUrl}=useAimsModule(),router=useRouter(),saving=ref(false),error=ref(''),operationKey=ref(''),form=reactive({projectCode:'',name:'',shortName:'',description:'',category:'product_dev',methodology:'PIVR',deptCode:'',leaderUid:'',securityLevel:'company',startDate:'',endDate:''});async function submit(){saving.value=true;error.value='';operationKey.value ||= crypto.randomUUID();try{const response=await $fetch<{code?:number,data?:{result?:{id?:number}}}>(moduleUrl('/api/v1/projects'),{method:'POST',headers:{'Idempotency-Key':operationKey.value},body:form});const id=response.data?.result?.id;if(response.code!==0||!id)throw Error('项目创建响应无效');operationKey.value='';await router.push(moduleUrl(`/projects/${id}`))}catch(e){error.value=e instanceof Error?e.message:'项目创建失败，可使用相同操作标识重试'}finally{saving.value=false}}</script>
<template><section class="mx-auto max-w-3xl space-y-5"><div><UButton :to="moduleUrl('/projects')" variant="link" color="neutral" icon="i-lucide-arrow-left">返回项目</UButton><h1 class="mt-1 text-2xl font-semibold text-highlighted">创建项目</h1></div><UAlert v-if="error" color="error" title="创建失败" :description="error"/><UCard><div class="grid gap-4 sm:grid-cols-2"><UFormField label="项目编码" required><UInput v-model="form.projectCode"/></UFormField><UFormField label="项目名称" required><UInput v-model="form.name"/></UFormField><UFormField label="项目简称" required><UInput v-model="form.shortName"/></UFormField><UFormField label="负责人 UID" required><UInput v-model="form.leaderUid"/></UFormField><UFormField label="部门编码"><UInput v-model="form.deptCode"/></UFormField><UFormField label="项目分类"><USelect v-model="form.category" :items="[{label:'产品研发',value:'product_dev'},{label:'交付项目',value:'delivery'},{label:'日常事务',value:'routine'},{label:'维护项目',value:'maintenance'}]"/></UFormField><UFormField label="开始日期"><UInput v-model="form.startDate" type="date"/></UFormField><UFormField label="结束日期"><UInput v-model="form.endDate" type="date"/></UFormField><UFormField label="说明" class="sm:col-span-2"><UTextarea v-model="form.description"/></UFormField></div><div class="mt-5 flex justify-end"><UButton :loading="saving" :disabled="!form.projectCode.trim()||!form.name.trim()||!form.shortName.trim()||!form.leaderUid.trim()" @click="submit">创建项目</UButton></div></UCard></section></template>
